/**
 * emit to subscription queries of type FindSemanticModel,
 * but only if the id matches
 *
 * @param		entity	SemanticModel
 */
	protected void emitFindSemanticModel( SemanticModel entity ) {
		LOGGER.info("handling emitFindSemanticModel" );
		
	    queryUpdateEmitter.emit(FindSemanticModelQuery.class,
	                            query -> query.getFilter().getSemanticModelId().equals(entity.getSemanticModelId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllSemanticModel
	 * 
	 * @param		entity	SemanticModel
	 */
	protected void emitFindAllSemanticModel( SemanticModel entity ) {
		LOGGER.info("handling emitFindAllSemanticModel" );
		
	    queryUpdateEmitter.emit(FindAllSemanticModelQuery.class,
	                            query -> true,
	                            entity);
	}

